## Code Example

```javascript
function findMissingAndDuplicate(arr){
  const n = arr.length;
  for(let i=0;i<n;i++){
    while(arr[i]>=1 && arr[i]<=n && arr[arr[i]-1] !== arr[i]){
      const target = arr[i]-1;
      [arr[i], arr[target]] = [arr[target], arr[i]];
    }
  }
  let missing = -1, dup = -1;
  for(let i=0;i<n;i++){
    if(arr[i] !== i+1){
      missing = i+1;
      dup = arr[i];
      break;
    }
  }
  return {missing, dup};
}
```

